using System.Text.Json.Serialization;

namespace AutonomousAgentHub.Core.Contracts;

/// <summary>
/// Polyglot build and regression test report generated by <c>Stage5TesterAgent</c>.
/// </summary>
public sealed class Stage5TestReportArtifact
{
    [JsonPropertyName("passed")]
    public bool Passed { get; init; }

    [JsonPropertyName("totalAttempts")]
    public int TotalAttempts { get; init; }

    [JsonPropertyName("detectedStack")]
    public string DetectedStack { get; init; } = string.Empty;

    [JsonPropertyName("buildCommandExecuted")]
    public string BuildCommandExecuted { get; init; } = string.Empty;

    [JsonPropertyName("testCommandExecuted")]
    public string TestCommandExecuted { get; init; } = string.Empty;

    [JsonPropertyName("attemptLogs")]
    public List<TestExecutionAttempt> AttemptLogs { get; init; } = [];

    [JsonPropertyName("hardResetTriggered")]
    public bool HardResetTriggered { get; init; }
}

/// <summary>
/// Captures stdout, stderr, exit code, and timing for a single build + test attempt.
/// </summary>
public sealed class TestExecutionAttempt
{
    [JsonPropertyName("attemptNumber")]
    public int AttemptNumber { get; init; }

    [JsonPropertyName("buildSucceeded")]
    public bool BuildSucceeded { get; init; }

    [JsonPropertyName("testsSucceeded")]
    public bool TestsSucceeded { get; init; }

    [JsonPropertyName("exitCode")]
    public int ExitCode { get; init; }

    [JsonPropertyName("durationMs")]
    public long DurationMs { get; init; }

    [JsonPropertyName("standardOutput")]
    public string StandardOutput { get; init; } = string.Empty;

    [JsonPropertyName("standardError")]
    public string StandardError { get; init; } = string.Empty;

    [JsonPropertyName("failureSummary")]
    public string? FailureSummary { get; init; }
}

